349	    private static boolean isBlank(String value) {
350	        return value == null || value.isBlank();
351	    }
352	
353	    /**
354	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
355	     * rolled forward, just as a weekend is, to the next non-holiday business day.
356	     */
357	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
358	        LocalDate.of(2026, 1, 1),
359	        LocalDate.of(2026, 1, 26),
360	        LocalDate.of(2026, 4, 25),
361	        LocalDate.of(2026, 12, 25),
362	        LocalDate.of(2026, 12, 28));
363	
364	    /**
365	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
366	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
367	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
368	     * registration date (whether supplied in the request or defaulted to the server date), so every
369	     * value derived from the registration date sees the adjusted business day.
370	     */
371	    private static LocalDate toBusinessDay(LocalDate date) {
372	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
373	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
374	                || PUBLIC_HOLIDAYS.contains(date)) {
375	            date = date.plusDays(1);
376	        }
377	        return date;
378	    }
379	
380	    /**
381	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
382	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
383	     * lower-cased so that last names are compared case-insensitively.
384	     */
385	    private static String normalizeHousehold(String value) {
386	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
387	    }
388	
389	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
390	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
391	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
392	
393	    /**
394	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
395	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
396	     * upper-cased, and common street-type abbreviations are expanded token-by-token
397	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
398	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
399	     * used for every address comparison (household-duplicate detection and the shared household id).
400	     */
401	    private static String normalizeAddress(String value) {
402	        if (value == null) {
403	            return "";
404	        }
405	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
406	        if (collapsed.isEmpty()) {
407	            return "";
408	        }
409	        String[] tokens = collapsed.split(" ");
410	        StringBuilder sb = new StringBuilder();
411	        for (int i = 0; i < tokens.length; i++) {
412	            if (i > 0) {
413	                sb.append(' ');
414	            }
415	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
416	        }
417	        return sb.toString();
418	    }
419	
420	    /**
421	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
422	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
423	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
424	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
425	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
426	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
427	     * The resulting {@code address} is the effective value every address reader sees, and is blank
428	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
429	     */
430	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
431	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
432	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
433	        if (!isBlank(line1)) {
434	            ownerFieldsDto.setAddressLine1(line1);
435	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
436	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
437	        } else {
438	            ownerFieldsDto.setAddressLine1(null);
439	            ownerFieldsDto.setAddressLine2(null);
440	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
441	        }
442	    }
443	
444	    /**
445	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
446	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
447	     * deterministic function of the normalized last name and postcode, so every owner that shares
448	     * those values maps to the same identifier regardless of creation order. A {@code null}
449	     * postcode contributes the empty string.
450	     */
451	    private static String householdId(String normalizedLastName, String postcode) {
452	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
453	        return sha256Hex12(key);
454	    }
455	
456	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
457	    private static String sha256Hex12(String s) {
458	        try {
459	            byte[] digest = MessageDigest.getInstance("SHA-256")
460	                .digest(s.getBytes(StandardCharsets.UTF_8));
461	            StringBuilder sb = new StringBuilder(12);
462	            for (int i = 0; i < 6; i++) {
463	                sb.append(String.format("%02x", digest[i]));
464	            }
465	            return sb.toString();
466	        }
467	        catch (NoSuchAlgorithmException e) {
468	            throw new IllegalStateException("SHA-256 not available", e);
469	        }
470	    }
471	
472	    /**
473	     * Builds the {@code customerCode} assigned to a new owner, formatted
474	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
475	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
476	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
477	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
478	     * pure function of the owner's own identity fields.
479	     */
480	    private static String customerCode(String postcode, String telephone, String lastName) {
481	        String region = LocalityDeriver.region(postcode);
482	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
483	            + (lastName == null ? "" : lastName));
484	        return region + "-" + hash8;
485	    }
486	
487	    /**
488	     * De-duplicates a computed {@code customerCode} against the codes already assigned to existing
489	     * owners. If {@code base} is not currently in use it is returned unchanged; otherwise
490	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
491	     * existing owner holds (e.g. a second collision on {@code 'NSW-1A2B3C4D'} becomes
492	     * {@code 'NSW-1A2B3C4D-2'}, a third {@code 'NSW-1A2B3C4D-3'}, and so on).
493	     */
494	    private String deduplicateCustomerCode(String base) {
495	        Set<String> existing = this.clinicService.findAllOwners().stream()
496	            .map(Owner::getCustomerCode)
497	            .filter(code -> code != null)
498	            .collect(Collectors.toSet());
499	        if (!existing.contains(base)) {
500	            return base;
501	        }
502	        int n = 2;
503	        while (existing.contains(base + "-" + n)) {
504	            n++;
505	        }
506	        return base + "-" + n;
507	    }
508	
509	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
510	    private static String sha256Hex8(String s) {
511	        try {
512	            byte[] digest = MessageDigest.getInstance("SHA-256")
513	                .digest(s.getBytes(StandardCharsets.UTF_8));
514	            StringBuilder sb = new StringBuilder(8);
515	            for (int i = 0; i < 4; i++) {
516	                sb.append(String.format("%02X", digest[i]));
517	            }
518	            return sb.toString();
519	        }
520	        catch (NoSuchAlgorithmException e) {
521	            throw new IllegalStateException("SHA-256 not available", e);
522	        }
523	    }
524	
525	    /**
526	     * Counts the existing owners that share the given first name and last name, compared
527	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
528	     * owner currently being created is saved), so it reflects how many namesakes preceded the
529	     * new owner.
530	     */
531	    private int countNamesakes(String firstName, String lastName) {
532	        return (int) this.clinicService.findAllOwners().stream()
533	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
534	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
535	            .count();
536	    }
537	
538	    /**
539	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
540	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
541	     * national one, a single leading {@code '0'} is dropped, and the default country code
542	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
543	     * national number must have the length required by its country code ({@code '+61'} requires 9
544	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
545	     * raised (reported to the client as 400).
546	     */
547	    private static String toE164(String telephone) {
548	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
549	        String digits;
550	        if (cleaned.startsWith("+")) {
551	            digits = cleaned.substring(1);
552	        } else {
553	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
554	            digits = "61" + national;
555	        }
556	        if (!digits.matches("[0-9]{8,15}")) {
557	            throw new InvalidTelephoneException(
558	                "telephone must form a valid E.164 number with 8 to 15 digits");
559	        }
560	        validateNationalLength(digits);
561	        return "+" + digits;
562	    }
563	
564	    /** National-number length required for each supported country code (digits after the code). */
565	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
566	        "61", 9, "1", 10);
567	
568	    /**
569	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
570	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
571	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
572	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
573	     */
574	    private static void validateNationalLength(String digits) {
575	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
576	            String code = entry.getKey();
577	            if (digits.startsWith(code)) {
578	                int nationalLength = digits.length() - code.length();
579	                if (nationalLength != entry.getValue()) {
580	                    throw new InvalidTelephoneException(
581	                        "telephone national number must have " + entry.getValue()
582	                            + " digits for country code +" + code);
583	                }
584	                return;
585	            }
586	        }
587	    }
588	
589	    /**
590	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
591	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
592	     * any 4-digit postcode.
593	     */
594	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
595	        "NSW", new int[] {2000, 2099},
596	        "VIC", new int[] {3000, 3099},
597	        "QLD", new int[] {4000, 4099});
598	
599	    /**
600	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
601	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
602	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
603	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
604	     * no known region accepts any 4-digit postcode. A violation raises an
605	     * {@link InvalidPostcodeException} (reported to the client as 400).
606	     */
607	    private static void validatePostcode(String city, String postcode) {
608	        if (isBlank(postcode)) {
609	            return;
610	        }
611	        if (!postcode.matches("[0-9]{4}")) {
612	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
613	        }
614	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
615	        if (range == null) {
616	            return;
617	        }
618	        int value = Integer.parseInt(postcode);
619	        if (value < range[0] || value > range[1]) {
620	            throw new InvalidPostcodeException(
621	                "postcode is out of range for the owner's city region");
622	        }
623	    }
624	
625	    /**
626	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
627	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
628	     * check).
629	     */
630	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
631	        "mailinator.com", "tempmail.com", "guerrillamail.com");
632	
633	    /**
634	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
635	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
636	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
637	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
638	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
639	     * so it is stored and returned in canonical form.
640	     */
641	    private static String normalizeEmail(String email) {
642	        if (isBlank(email)) {
643	            return null;
644	        }
645	        String trimmed = email.trim();
646	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
647	            throw new InvalidEmailException("email must be a syntactically valid address");
648	        }
649	        String normalized = trimmed.toLowerCase(Locale.ROOT);
650	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
651	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
652	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
653	        }
654	        return normalized;
655	    }
656	}
